/**
 * Rendering benchmark for standalone HiPlot pages.
 *
 * Drives each page generated by `bench/make_experiments.py` in headless
 * Chromium and records, per page load:
 *   - payload: HTML size, the time spent decoding the embedded experiment, and
 *     the DOMContentLoaded end (HTML parse plus the synchronous setup script);
 *   - initial: navigation start to the last line draw call of the first render;
 *   - redraw: a color-by change to the last draw call of the full redraw;
 *   - brush drag: frame intervals while a brush is dragged one step per frame;
 *   - brush end: mouse-up to the last line draw, and to the last table update.
 *
 * Instrumentation is installed from outside the bundle, so every version of
 * HiPlot is measured the same way: Canvas2D `stroke`/`fill` and WebGL `draw*`
 * calls count as line draws; `JSON.parse`/`eval` calls on strings over 1 MB
 * count as payload decoding; a mutation observer on the table container
 * timestamps table updates.
 *
 * Usage:
 *   bun bench/run.ts --dir <html dir> [--reps 3] [--out results.json] [--label name]
 */

import { readdirSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { parseArgs } from "node:util";
import { chromium, type Page } from "@playwright/test";

const SETTLE_QUIET_MS = 500;
const SETTLE_QUIET_FRAMES = 20;
const SETTLE_TIMEOUT_MS = 240_000;
const DRAG_FRAMES = 120;
const STALL_MS = 50;

interface PageProbe {
  draws: number;
  lastDraw: number;
  frameCount: number;
  framesAtLastDraw: number;
  decodeMs: number;
  tableMutations: number;
  lastTableMutation: number;
}

interface DragStats {
  frames: number;
  durationMs: number;
  p50Ms: number;
  p95Ms: number;
  maxMs: number;
  stalls: number;
  longTaskMs: number;
}

interface RepResult {
  decodeMs: number;
  domReadyMs: number;
  initialDrawnMs: number;
  redrawMs: number;
  drag: DragStats;
  brushEndLinesMs: number;
  brushEndTableMs: number;
  jsHeapMB: number;
}

interface SizeResult {
  file: string;
  htmlMB: number;
  reps: RepResult[];
  median: RepResult;
}

declare global {
  interface Window {
    __bench: PageProbe;
    hiplot_last_instance: {
      state: { colorby: string; params_def: Record<string, { type: string }> };
      setState: (state: { colorby: string }) => void;
    };
  }
}

/** Installed before any page script runs. Must stay self-contained (it is serialized). */
function installProbe(): void {
  const probe: PageProbe = {
    draws: 0,
    lastDraw: 0,
    frameCount: 0,
    framesAtLastDraw: 0,
    decodeMs: 0,
    tableMutations: 0,
    lastTableMutation: 0,
  };
  window.__bench = probe;
  const countFrames = (): void => {
    probe.frameCount += 1;
    requestAnimationFrame(countFrames);
  };
  requestAnimationFrame(countFrames);

  const wrapDraw = (proto: object | undefined, name: string): void => {
    if (proto === undefined || !(name in proto)) {
      return;
    }
    const target = proto as Record<string, (...args: unknown[]) => unknown>;
    const original = target[name];
    if (original === undefined) {
      return;
    }
    target[name] = function (this: unknown, ...args: unknown[]): unknown {
      probe.draws += 1;
      probe.lastDraw = performance.now();
      probe.framesAtLastDraw = probe.frameCount;
      return original.apply(this, args);
    };
  };
  for (const name of ["stroke", "fill"]) {
    wrapDraw(CanvasRenderingContext2D.prototype, name);
  }
  for (const ctor of [window.WebGLRenderingContext, window.WebGL2RenderingContext]) {
    for (const name of [
      "drawArrays",
      "drawElements",
      "drawArraysInstanced",
      "drawElementsInstanced",
    ]) {
      wrapDraw(ctor?.prototype, name);
    }
  }

  const DECODE_MIN_CHARS = 1_000_000;
  const originalParse = JSON.parse;
  JSON.parse = (text: string, reviver?: (key: string, value: unknown) => unknown) => {
    if (typeof text !== "string" || text.length < DECODE_MIN_CHARS) {
      return originalParse(text, reviver);
    }
    const start = performance.now();
    const parsed: unknown = originalParse(text, reviver);
    probe.decodeMs += performance.now() - start;
    return parsed;
  };
  // biome-ignore lint/security/noGlobalEval: wraps the page's own eval to time payload decoding.
  const originalEval = window.eval;
  window.eval = (code: string): unknown => {
    if (typeof code !== "string" || code.length < DECODE_MIN_CHARS) {
      return originalEval(code);
    }
    const start = performance.now();
    const evaluated: unknown = originalEval(code);
    probe.decodeMs += performance.now() - start;
    return evaluated;
  };

  const observeTable = (): void => {
    const container = document.querySelector(".sample-table-container");
    if (container === null) {
      requestAnimationFrame(observeTable);
      return;
    }
    new MutationObserver(() => {
      probe.tableMutations += 1;
      probe.lastTableMutation = performance.now();
    }).observe(container, { childList: true, subtree: true, characterData: true });
  };
  document.addEventListener("DOMContentLoaded", observeTable);
}

/**
 * Waits until no line has been drawn for a quiet period and returns the last draw
 * time. With `requireDraw`, at least one draw must follow `since`; otherwise a
 * quiet period right after `since` means the picture was already complete, and
 * `since` itself is returned.
 */
async function waitForDrawsToSettle(
  page: Page,
  since: number,
  requireDraw = true,
): Promise<number> {
  const handle = await page.waitForFunction(
    ({ since, quietMs, quietFrames, requireDraw }) => {
      const probe = window.__bench;
      const drewSince = probe.lastDraw > since;
      if (!drewSince) {
        return !requireDraw && performance.now() - since >= quietMs ? since : false;
      }
      const settled =
        performance.now() - probe.lastDraw >= quietMs &&
        probe.frameCount - probe.framesAtLastDraw >= quietFrames;
      return settled ? probe.lastDraw : false;
    },
    { since, quietMs: SETTLE_QUIET_MS, quietFrames: SETTLE_QUIET_FRAMES, requireDraw },
    { timeout: SETTLE_TIMEOUT_MS, polling: 100 },
  );
  return (await handle.jsonValue()) as number;
}

/** Like `waitForDrawsToSettle(page, since, false)`, for mutations of the table. */
async function waitForTableToSettle(page: Page, since: number): Promise<number> {
  const handle = await page.waitForFunction(
    ({ since, quietMs }) => {
      const probe = window.__bench;
      const last = Math.max(probe.lastTableMutation, since);
      return performance.now() - last >= quietMs ? last : false;
    },
    { since, quietMs: SETTLE_QUIET_MS },
    { timeout: SETTLE_TIMEOUT_MS, polling: 100 },
  );
  return (await handle.jsonValue()) as number;
}

async function measureRedraw(page: Page): Promise<number> {
  const durations: number[] = [];
  for (let attempt = 0; attempt < 2; attempt++) {
    const start = await page.evaluate(() => {
      const instance = window.hiplot_last_instance;
      const candidates = Object.keys(instance.state.params_def).filter(
        (column) => column.startsWith("numeric_") && column !== instance.state.colorby,
      );
      const next = candidates[0];
      if (next === undefined) {
        throw new Error("No numeric column to color by");
      }
      const startedAt = performance.now();
      instance.setState({ colorby: next });
      return startedAt;
    });
    const end = await waitForDrawsToSettle(page, start);
    durations.push(end - start);
  }
  return median(durations);
}

async function measureBrush(
  page: Page,
): Promise<{ drag: DragStats; mouseUpAt: number; dragStartedAt: number }> {
  return page.evaluate(
    ({ dragFrames, stallMs }) =>
      new Promise<{ drag: DragStats; mouseUpAt: number; dragStartedAt: number }>(
        (resolve, reject) => {
          type BrushOverlay = SVGRectElement & { __data__?: string };
          const overlays = Array.from(
            document.querySelectorAll<BrushOverlay>("svg g.dimension .pplot-brush rect.overlay"),
          );
          const overlay =
            overlays.find((element) => element.__data__ === "numeric_01") ?? overlays[0];
          if (overlay === undefined) {
            reject(new Error("No brush overlay found"));
            return;
          }
          const box = overlay.getBoundingClientRect();
          const x = box.left + box.width / 2;
          const yStart = box.top + box.height * 0.15;
          const yEnd = box.top + box.height * 0.65;
          const mouse = (type: string, target: EventTarget, y: number): void => {
            target.dispatchEvent(
              new MouseEvent(type, {
                bubbles: true,
                cancelable: true,
                view: window,
                clientX: x,
                clientY: y,
                button: 0,
              }),
            );
          };
          let longTaskMs = 0;
          const longTasks = new PerformanceObserver((list) => {
            for (const entry of list.getEntries()) {
              longTaskMs += entry.duration;
            }
          });
          longTasks.observe({ entryTypes: ["longtask"] });

          const frameTimes: number[] = [];
          const dragStartedAt = performance.now();
          mouse("mousedown", overlay, yStart);
          const step = (timestamp: number): void => {
            frameTimes.push(timestamp);
            const progress = frameTimes.length / dragFrames;
            if (frameTimes.length <= dragFrames) {
              mouse("mousemove", window, yStart + (yEnd - yStart) * progress);
              requestAnimationFrame(step);
              return;
            }
            const mouseUpAt = performance.now();
            mouse("mouseup", window, yEnd);
            longTasks.disconnect();
            const intervals = frameTimes.slice(1).map((time, index) => time - frameTimes[index]);
            const sorted = [...intervals].sort((a, b) => a - b);
            const quantile = (q: number): number =>
              sorted[Math.min(sorted.length - 1, Math.floor(q * sorted.length))];
            resolve({
              mouseUpAt,
              dragStartedAt,
              drag: {
                frames: intervals.length,
                durationMs: frameTimes[frameTimes.length - 1] - frameTimes[0],
                p50Ms: quantile(0.5),
                p95Ms: quantile(0.95),
                maxMs: sorted[sorted.length - 1],
                stalls: intervals.filter((interval) => interval > stallMs).length,
                longTaskMs,
              },
            });
          };
          requestAnimationFrame(step);
        },
      ),
    { dragFrames: DRAG_FRAMES, stallMs: STALL_MS },
  );
}

async function runOnce(page: Page, url: string): Promise<RepResult> {
  await page.goto(url, { waitUntil: "load", timeout: SETTLE_TIMEOUT_MS });
  const initialDrawnMs = await waitForDrawsToSettle(page, 0);
  const { decodeMs, domReadyMs } = await page.evaluate(() => {
    const [navigation] = performance.getEntriesByType(
      "navigation",
    ) as PerformanceNavigationTiming[];
    return {
      decodeMs: window.__bench.decodeMs,
      domReadyMs: navigation?.domContentLoadedEventEnd ?? Number.NaN,
    };
  });
  const redrawMs = await measureRedraw(page);
  const { drag, mouseUpAt } = await measureBrush(page);
  const linesSettledAt = await waitForDrawsToSettle(page, mouseUpAt, false);
  const tableSettledAt = await waitForTableToSettle(page, mouseUpAt);
  const jsHeapMB = await page.evaluate(
    () =>
      ((performance as unknown as { memory?: { usedJSHeapSize: number } }).memory?.usedJSHeapSize ??
        0) / 1e6,
  );
  return {
    decodeMs,
    domReadyMs,
    initialDrawnMs,
    redrawMs,
    drag,
    brushEndLinesMs: Math.max(0, linesSettledAt - mouseUpAt),
    brushEndTableMs: tableSettledAt - mouseUpAt,
    jsHeapMB,
  };
}

function median(values: number[]): number {
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 1 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
}

function medianResult(reps: RepResult[]): RepResult {
  const pick = (get: (rep: RepResult) => number): number => median(reps.map(get));
  return {
    decodeMs: pick((r) => r.decodeMs),
    domReadyMs: pick((r) => r.domReadyMs),
    initialDrawnMs: pick((r) => r.initialDrawnMs),
    redrawMs: pick((r) => r.redrawMs),
    drag: {
      frames: pick((r) => r.drag.frames),
      durationMs: pick((r) => r.drag.durationMs),
      p50Ms: pick((r) => r.drag.p50Ms),
      p95Ms: pick((r) => r.drag.p95Ms),
      maxMs: pick((r) => r.drag.maxMs),
      stalls: pick((r) => r.drag.stalls),
      longTaskMs: pick((r) => r.drag.longTaskMs),
    },
    brushEndLinesMs: pick((r) => r.brushEndLinesMs),
    brushEndTableMs: pick((r) => r.brushEndTableMs),
    jsHeapMB: pick((r) => r.jsHeapMB),
  };
}

function formatRow(label: string, result: SizeResult): string {
  const m = result.median;
  const ms = (value: number): string => value.toFixed(0);
  return [
    label,
    result.htmlMB.toFixed(1),
    ms(m.decodeMs),
    ms(m.domReadyMs),
    ms(m.initialDrawnMs),
    ms(m.redrawMs),
    `${ms(m.drag.p50Ms)} / ${ms(m.drag.p95Ms)} / ${ms(m.drag.maxMs)}`,
    `${m.drag.stalls}/${m.drag.frames}`,
    ms(m.brushEndLinesMs),
    ms(m.brushEndTableMs),
    m.jsHeapMB.toFixed(0),
  ].join(" | ");
}

async function main(): Promise<void> {
  const { values } = parseArgs({
    options: {
      dir: { type: "string" },
      reps: { type: "string", default: "3" },
      out: { type: "string" },
      label: { type: "string", default: "run" },
      headed: { type: "boolean", default: false },
    },
  });
  if (values.dir === undefined) {
    throw new Error("--dir is required");
  }
  const dir = path.resolve(values.dir);
  const reps = Number.parseInt(values.reps, 10);
  const files = readdirSync(dir)
    .filter((name) => /^bench-\d+x\d+\.html$/.test(name))
    .sort((a, b) => statSync(path.join(dir, a)).size - statSync(path.join(dir, b)).size);
  if (files.length === 0) {
    throw new Error(`No bench-*.html files in ${dir}`);
  }

  // The full Chromium build in new-headless mode keeps GPU acceleration, which the
  // headless shell lacks; WebGL numbers are meaningless on a software rasterizer.
  const browser = await chromium.launch({
    channel: "chromium",
    headless: !values.headed,
    args: ["--enable-precise-memory-info", "--enable-gpu-rasterization", "--ignore-gpu-blocklist"],
  });
  const results: Record<string, SizeResult> = {};
  let renderer = "unknown";
  try {
    const context = await browser.newContext({
      viewport: { width: 1600, height: 1000 },
      deviceScaleFactor: 1,
    });
    await context.addInitScript(installProbe);
    const page = await context.newPage();
    renderer = await page.evaluate(() => {
      const gl = document.createElement("canvas").getContext("webgl");
      const info = gl?.getExtension("WEBGL_debug_renderer_info");
      return gl && info ? String(gl.getParameter(info.UNMASKED_RENDERER_WEBGL)) : "no webgl";
    });
    for (const file of files) {
      const url = pathToFileURL(path.join(dir, file)).href;
      const runs: RepResult[] = [];
      for (let rep = 0; rep < reps; rep++) {
        runs.push(await runOnce(page, url));
        process.stderr.write(`${file} rep ${rep + 1}/${reps} done\n`);
      }
      results[file] = {
        file,
        htmlMB: statSync(path.join(dir, file)).size / 1e6,
        reps: runs,
        median: medianResult(runs),
      };
    }
  } finally {
    await browser.close();
  }

  const header =
    "size | HTML MB | decode ms | DOM ready ms | initial drawn ms | full redraw ms | drag frame p50 / p95 / max ms | stalls >50ms | brush end → lines ms | brush end → table ms | JS heap MB";
  console.log(`# ${values.label} (WebGL renderer: ${renderer})`);
  console.log(header);
  console.log(header.replace(/[^|]+/g, "---"));
  for (const [file, result] of Object.entries(results)) {
    const [, rows, columns] = /^bench-(\d+)x(\d+)\.html$/.exec(file) ?? [];
    console.log(formatRow(`${Number(rows) / 1000}k × ${columns}`, result));
  }
  if (values.out !== undefined) {
    writeFileSync(
      values.out,
      JSON.stringify({ label: values.label, renderer, results }, null, 2),
      "utf-8",
    );
  }
}

await main();
